INSERT INTO `contact_inquiries` (`id`, `name`, `email`, `phone`, `message`, `created_at`) VALUES
(3, 'Daniel Wright', 'daniel.wright@jmailservice.com', '8054002077', 'When someone searches for your service, you should be the first thing they see.\n\nWe make that happen.\n\nNo long learning curve. No complicated campaigns. Just targeted search traffic based on the keywords you choose.\n\nInterested?\n\nSend your website and keyword list, and I&#039;ll send you guaranteed traffic numbers along with pricing options.\n\nLet&#039;s put you in front of ready buyers.', '2026-04-21 06:14:44'),
(4, 'Alexander Reid', 'alexander.reid@jmailservice.com', '8054002077', 'What would steady, targeted search traffic mean for your business?\n\nOur platform delivers visitors based on specific keywords in your industry. You choose the terms. We guarantee the traffic. If we fall short, we add more keywords at no charge until we hit the commitment.\n\nIf this sounds interesting, send:\n - Your website\n - Your preferred keywords\n\nI&#039;ll respond with traffic guarantees and pricing options.', '2026-05-04 23:47:18'),
(5, 'Thomas Walker', 'thomas.walker@jmailservice.com', '8054002077', 'Imagine your brand appearing first when customers search online. That&#039;s exactly what we do - and we can launch it within a day.\nAre you interested in more details?', '2026-05-24 22:26:28'),
(6, 'Nathaniel Brooks', 'nathaniel.brooks@jmailservice.com', '8054002077', 'We place your business right where people are already searching for your services - setup usually takes less than 24 hours.\nAre you interested?', '2026-06-13 09:05:09'),
(7, 'William Grant', 'william.grant@jmailservice.com', '8054002077', 'We can place your company ahead of competitors in search - and you&#039;ll see it live within 24 hours.\nDo you want to get on board?', '2026-07-06 06:23:43'),
(8, 'Alexander Reid', 'alexander.reid@jmailservice.com', '8054002077', 'We make it easy to capture customers at the exact moment they&#039;re searching online. Our system places your brand at the top of search results within a single day, and all clicks lead directly to your website.\nYou can track everything yourself inside Google Analytics.\nWould you like a short overview of how it works?', '2026-07-30 05:21:29'),
(9, 'Nathaniel Brooks', 'nathaniel.brooks@jmailservice.com', '8054002077', 'If I could get your business in front of hundreds of local searchers by tomorrow - would you be interested?', '2026-08-18 06:45:06');

