INSERT INTO `pages` (`id`, `page_slug`, `page_title`, `content`, `updated_at`) VALUES
(1, 'about-us', 'About Us', '<p>Your Destination for Stylish Ladies Outfits !</p>\n\n<p>Welcome to Pragati Kurtis! We are your go-to manufacturer and wholesale supplier of trendy ladies’ outfits. From elegant kurtis to chic afghani pant suits, aalia cut suits, and more, we have a wide range of fashionable options to suit your style.\n\nAt Pragati Kurties, we prioritize quality and fashion-forward designs. Our skilled artisans meticulously create each garment, ensuring exceptional craftsmanship and attention to detail. We source the finest fabrics, making our outfits not only stylish but also incredibly comfortable to wear.\n\nWhether you’re a retailer or a boutique owner, we offer competitive prices and flexible order quantities to meet your business needs. With efficient delivery options, we make it convenient for you to stock your shelves with our high-quality outfits.\n\nCustomer satisfaction is our top priority. Our friendly customer support team is always ready to assist you, providing a seamless shopping experience from start to finish. We value your trust and aim to build long-lasting relationships with our clients.</p>', '2026-01-02 11:58:33'),
(2, 'contact-us', 'Contact Us', '<p>We’d love to hear from you! Whether you have a question, need support, or want to discuss a business opportunity, our team is here to help. Reach out to us through any of the channels below, and we’ll get back to you as soon as possible.</p>', '2026-01-08 02:51:20');

