INSERT INTO `products` (`id`, `name`, `description`, `meta_title`, `meta_description`, `price`, `dealer_price`, `category`, `hsn_code`, `fabric`, `occasion`, `color`, `stock`, `sizes`, `image_url`, `variant_images`, `created_at`) VALUES
(6, '3 Pic Suit Set', 'Step into effortless elegance with this beautifully designed Indigo Blue kurta set, perfect for everyday sophistication. The kurta features a graceful V-neckline highlighted with delicate printed detailing, while the all-over traditional motif print adds a timeless ethnic charm.\r\n\r\nThe straight-cut kurta is paired with matching printed pants that ensure comfort and ease of movement. Completing the look is a coordinated dupatta with a subtle zig-zag pattern and decorative borders, adding depth and visual appeal to the ensemble.\r\n\r\nCrafted from soft, breathable fabric, this set is ideal for office wear, casual outings, festive mornings, or relaxed gatherings. Pair it with minimal jewelry and flats for a refined, understated look.', 'Elegant Indigo Blue Printed Kurta Set with Dupatta', '3-piece set: Kurta, Pant & Dupatta\r\n\r\nElegant ethnic prints\r\n\r\nComfortable straight-fit silhouette\r\n\r\nStylish V-neck design\r\n\r\nLightweight & breathable fabric\r\n\r\nPerfect for daily and semi-formal wear', 1395.00, 1395.00, 'Suit Set', 'HSN', 'Cotton', 'Casual', 'Single', 1, '38, 40, 42, 44, 46', 'https://www.pragatikurtis.com/backend/uploads/1770347581_main_69855c3d8ff6c.jpg', NULL, '2026-02-06 03:13:01'),
(7, '3 Pic Suit Set', 'Bring timeless charm to your wardrobe with this beautifully designed printed kurta set, crafted for everyday comfort and graceful style. The kurta features a subtle all-over ethnic print with an elegant V-neckline, enhanced by delicate detailing that adds a refined touch. The straight silhouette offers a flattering and relaxed fit.\r\n\r\nThe set is paired with matching printed bottoms, designed for ease and all-day wear. Completing the look is a coordinated dupatta, adorned with traditional floral motifs and a decorative border, adding flow and sophistication to the ensemble.\r\n\r\nMade from soft, breathable fabric, this kurta set is perfect for daily wear, office wear, casual outings, festive mornings, or family gatherings. Style it with juttis or sandals and minimal accessories for a graceful ethnic look.', 'Printed Kurta Set with Dupatta – Classic Ethnic Elegance', '3-piece set: Kurta, Pant & Dupatta\r\n\r\nElegant traditional prints\r\n\r\nComfortable straight-fit design\r\n\r\nStylish V-neckline\r\n\r\nLightweight & skin-friendly fabric\r\n\r\nSuitable for casual & semi-festive occasions', 1795.00, 1795.00, 'Suit Set', 'HSN', 'Cotton', 'Casual', 'Single', 1, '38, 40, 42, 44', 'https://www.pragatikurtis.com/backend/uploads/1770347701_main_69855cb5630f9.jpg', NULL, '2026-02-06 03:15:01'),
(8, 'Crape Sharara', 'Make a graceful statement with this exquisitely crafted designer kurta sharara set, inspired by timeless heritage aesthetics. The kurta features an elegant straight silhouette adorned with intricate floral and ornamental prints, beautifully balanced with detailed borders for a regal finish. The neckline is highlighted with refined detailing, adding sophistication to the overall look.\r\n\r\nPaired with a flowy sharara, designed with coordinated floral prints and a wide flare, this ensemble offers both comfort and dramatic elegance. The look is completed with a matching dupatta, enhanced with delicate borders and traditional motifs that add movement and charm.\r\n\r\nCrafted from soft, breathable fabric with a luxurious fall, this outfit is ideal for festive occasions, weddings, celebrations, and ethnic gatherings. Style it with statement earrings and heels for a truly elegant appearance.', 'Designer Floral Printed Kurta Sharara Set with Dupatta', '3-piece set: Kurta, Sharara & Dupatta\r\n\r\nRich floral & ornamental print\r\n\r\nElegant straight-fit kurta\r\n\r\nFlared sharara for a graceful look\r\n\r\nSoft, premium-feel fabric\r\n\r\nPerfect for festive & special occasions', 2995.00, 2995.00, 'Sharara', 'HASN', 'Crap', 'Casual', 'Single', 1, '40, 42, 44, 46', 'https://www.pragatikurtis.com/backend/uploads/1770347832_main_69855d383c58c.jpg', NULL, '2026-02-06 03:17:12'),
(9, 'Crape Sharara', 'Elevate your ethnic style with this exquisitely designed kurta sharara set, crafted for women who love timeless elegance with a touch of grandeur. The kurta features a deep, earthy base adorned with bold floral motifs and intricate traditional patterns. The beautifully detailed square neckline panel adds a regal focal point, enhancing the overall richness of the design.\r\n\r\nThe kurta is paired with a gracefully flared sharara, highlighted with coordinated floral prints and ornate borders that create a stunning flow with every step. Completing the ensemble is a matching dupatta, detailed with traditional borders and floral accents, adding depth and sophistication to the look.\r\n\r\nMade from soft, breathable fabric with a luxurious drape, this outfit is perfect for festive celebrations, weddings, evening functions, and special occasions. Pair it with statement jewelry and heels for an effortlessly elegant appearance.', 'Luxury Floral Printed Kurta Sharara Set with Dupatta', '3-piece set: Kurta, Sharara & Dupatta\r\n\r\nRich floral and traditional prints\r\n\r\nDesigner square neckline with detailed panel\r\n\r\nFlared sharara for a graceful silhouette\r\n\r\nPremium-feel, comfortable fabric\r\n\r\nIdeal for festive & occasion wear', 2895.00, 2895.00, 'Sharara', 'HASN', 'Crape', 'Casual', 'Single', 1, '38, 40, 42, 44, 46', 'https://www.pragatikurtis.com/backend/uploads/1770347939_main_69855da3aa12e.jpg', NULL, '2026-02-06 03:18:59'),
(10, 'Crape Silk Suit Set', 'The outfit appears to be a green printed salwar kameez set with intricate floral and geometric patterns in soft blues, creams, and earthy tones. The kameez has a straight cut with detailed panel-style prints down the front, giving it a refined, handcrafted feel. The dupattā is draped over one shoulder and flows down the side, matching the suit with coordinated prints and subtle tassel details along the edge.\r\n\r\nShe’s paired it with solid green churidar-style pants and simple brown flat sandals, keeping the look comfortable and understated. Her accessories are minimal but classic—traditional jhumka earrings and a small bindi—which nicely complement the ethnic vibe.\r\n\r\nHer hair is worn long and loose, softly styled, and her expression is warm and relaxed. The background looks like a narrow street or heritage area, which adds to the timeless, cultural aesthetic of the whole look.\r\n\r\nOverall, the style feels calm, classy, and very wearable, perfect for a festive day outing, casual traditional event, or even a relaxed family function.', 'She’s wearing a graceful, traditional Indian outfit and looks effortlessly elegant.', 'The outfit appears to be a green printed salwar kameez set with intricate floral and geometric patterns in soft blues, creams, and earthy tones. The kameez has a straight cut with detailed panel-style prints down the front, giving it a refined, handcrafte', 2295.00, 2295.00, 'Suit Set', 'HASN', 'Silk', 'Casual', 'Single', 1, '38, 40, 42, 44, 46', 'https://www.pragatikurtis.com/backend/uploads/1770348105_main_69855e49c4ace.jpg', NULL, '2026-02-06 03:21:45'),
(11, 'Pure Cotron Short Kurtis', 'The kurta features repeating floral block-style motifs in earthy red and beige tones, giving it a classic handcrafted look. The V-notch neckline is simple and neat, with subtle detailing that keeps the focus on the print. The three-quarter sleeves make it practical and comfortable, perfect for daily wear or casual outings.\r\n\r\nHer styling is minimal and graceful. She’s accessorized with oxidized silver jhumka earrings and a small black bindi, which beautifully complement the ethnic feel of the outfit. Her hair is worn long, loose, and softly styled, framing her face naturally.\r\n\r\nThe makeup is soft and understated—natural skin, light blush, and neutral lips—enhancing her calm expression. The light pastel background adds a clean, modern contrast, making the kurta’s deep green color stand out nicely.\r\n\r\nOverall, the look feels simple, classy, and effortlessly traditional, ideal for office wear, casual gatherings, or relaxed festive days.', 'She’s wearing a dark green printed kurta with a calm, elegant everyday-traditional vibe.', 'The kurta features repeating floral block-style motifs in earthy red and beige tones, giving it a classic handcrafted look. The V-notch neckline is simple and neat, with subtle detailing that keeps the focus on the print. The three-quarter sleeves make it', 595.00, 595.00, 'Kurtis', 'HSN', 'Cotron', 'Casual', 'Single', 1, '36, 38, 40, 42, 44', 'https://www.pragatikurtis.com/backend/uploads/1770348242_main_69855ed2de23d.jpg', NULL, '2026-02-06 03:24:02'),
(12, 'Dola Silk Suit Set', 'The kameez is richly adorned with gold embroidery, especially around the neckline, which features an ornate, heavily embellished panel that immediately draws the eye. Small, evenly spaced embroidered motifs are scattered across the fabric, adding texture without overwhelming the look. The hemline is finished with an intricate gold border, giving the outfit a refined, royal touch. The three-quarter sleeves also carry delicate embroidery along the edges.\r\n\r\nShe’s paired it with matching magenta straight-cut pants, finished with coordinated embroidered borders at the ankles. The dupattā, draped elegantly and trailing to the side, mirrors the outfit with subtle embellishments and a detailed edge, adding flow and drama.\r\n\r\nHer accessories elevate the look—statement gold jhumka earrings and traditional embroidered juttis that complement the gold detailing beautifully. Her hair is styled sleek and pulled back, enhancing the sharp, confident silhouette of the outfit.\r\n\r\nSet against a classical backdrop with sculpted pillars and statues, the overall look feels grand, poised, and ceremonial, perfect for weddings, festive evenings, or formal cultural events.', 'She’s wearing a bold, regal magenta salwar kameez set that feels luxurious and festive.', 'The kameez is richly adorned with gold embroidery, especially around the neckline, which features an ornate, heavily embellished panel that immediately draws the eye. Small, evenly spaced embroidered motifs are scattered across the fabric, adding texture ', 2695.00, 2695.00, 'Suit Set', 'HSN', 'Dola Silk', 'Casual', 'Single', 1, '38, 40, 42, 44', 'https://www.pragatikurtis.com/backend/uploads/1770348366_main_69855f4ebf40a.jpg', NULL, '2026-02-06 03:26:06'),
(13, '3 Pic Suit Set', 'Color & Fabric: The set is in a soothing slate grey / blue-grey tone, likely cotton or cotton-blend, perfect for comfort wear.\r\n\r\nKurta: Straight-cut kurta with all-over traditional block-style motifs in a lighter shade. It has a round neckline with a neatly detailed printed placket and 3/4th sleeves, keeping it classy and versatile.\r\n\r\nBottom: Paired with matching solid pants in a slightly darker grey, giving a clean and balanced look.\r\n\r\nDupatta: A coordinated printed dupatta with a subtle border, flowing and lightweight, adding elegance without overpowering the outfit.\r\n\r\nOverall Look: Simple, refined, and very wearable—ideal for daily wear, office, casual outings, or small festive gatherings.\r\n\r\nStyling Touch: Minimal jewelry and neutral footwear complement the understated charm of the suit.\r\n\r\nIf you want, I can also help write a product description for an online store, suggest fabric details, or create Instagram captions for this suit set', 'This is a graceful ethnic suit set with a very calm, elegant vibe', 'Color & Fabric: The set is in a soothing slate grey / blue-grey tone, likely cotton or cotton-blend, perfect for comfort wear.\r\n\r\nKurta: Straight-cut kurta with all-over traditional block-style motifs in a lighter shade. It has a round neckline with a nea', 1495.00, 1495.00, 'Suit sET', 'HSN', 'Cotton', 'Casual', 'Multi Color', 1, '38, 40, 42, 44, 46', 'https://www.pragatikurtis.com/backend/uploads/1770427379_main_698693f35d408.jpg', NULL, '2026-02-07 01:22:59'),
(15, 'Sleeveless Plazo Set', 'A Sleeveless Palazzo Set is a modern Indian ethnic outfit known for its comfort and elegant look.\r\n\r\nIt usually includes:\r\n\r\nA sleeveless kurti (top)\r\nWide-leg palazzo pants\r\nAn optional dupatta\r\n\r\nThis outfit is popular because it is lightweight, breathable, and stylish, making it perfect for hot weather. It gives a graceful and relaxed look while still feeling traditional.\r\n\r\nYou can wear it for daily use, office, or small functions and festivals like Diwali and Eid.', 'Sleeveless Plazo Set', 'A Sleeveless Palazzo Set is a modern Indian ethnic outfit known for its comfort and elegant look.\r\n\r\nIt usually includes:\r\n\r\nA sleeveless kurti (top)\r\nWide-leg palazzo pants\r\nAn optional dupatta\r\n\r\nThis outfit is popular because it is lightweight, breatha', 1995.00, 1995.00, 'Plazo Set', 'hsn', 'Cotton', 'Casual', 'Multi', 1, '38,40,42,44', 'https://www.pragatikurtis.com/backend/uploads/1775623161_main_69d5dbf9d8844.jpg', NULL, '2026-04-08 04:39:21'),
(16, 'Anarkali Suit Set', 'An Anarkali suit is a long, frock-style kurta that is fitted at the top and flares beautifully from the waist down, creating a royal and flowy look. This design dates back to the Mughal era and remains a timeless fashion choice today.\r\n\r\nWhen made in pure (Mul) cotton, it becomes even more special because of its comfort and breathable nature.', 'Anarkali', 'An Anarkali suit is a long, frock-style kurta that is fitted at the top and flares beautifully from the waist down, creating a royal and flowy look. This design dates back to the Mughal era and remains a timeless fashion choice today.\r\n\r\nWhen made in pure', 2195.00, 2195.00, 'Anarkali Suits', 'hsn', 'Mul Cotton', 'Casual', 'Single', 1, 'M,L,XL,XXL', 'https://www.pragatikurtis.com/backend/uploads/1775696679_main_69d6fb274efae.jpg', NULL, '2026-04-09 01:04:39');

